-- 0112_rouen_water_no_capture.sql
-- GRYD — La Seine cesse d'être capturable (MASTER SPEC-GEO, lot B1).
--
-- ═══ LE DÉFAUT ═════════════════════════════════════════════════════════════
-- Le mécanisme de zone interdite EXISTE depuis `0002` et il MARCHE :
-- `loadNoCaptureHexes` (ingest_run) lit `no_capture_zones`, applique un
-- point-in-polygon, et `decideClaims` refuse la cellule avec l'issue
-- `blocked_no_capture_zone`. Une seule chose manquait : la TABLE ÉTAIT VIDE.
--
-- Conséquence, jusqu'à ce commit : une boucle qui longe les deux rives capture
-- le fleuve. Ce n'est pas qu'inélégant — c'est ~9 km² de territoire gratuit au
-- centre de la ville de lancement, impossible à défendre puisque personne n'y
-- court, et un plafond d'aire atteint sans effort.
--
-- ═══ LA DONNÉE EST RÉELLE, ET SOURCÉE ══════════════════════════════════════
-- Géométrie extraite d'OpenStreetMap via l'API Overpass le 03/08/2026 :
-- relations `type=multipolygon` + `natural=water` et surfaces `water=river`
-- dans la boîte (49.38-49.50 N, 0.98-1.22 E). Les membres `outer` ouverts ont
-- été RECOLLÉS en anneaux fermés, puis simplifiés à 8 m (Douglas-Peucker).
--
-- Pourquoi 8 m : la propriété se décide sur une grille H3 res 10 (~65 m de
-- côté). Une frontière d'eau au mètre près n'y changerait AUCUNE cellule ; en
-- revanche 1 080 sommets au lieu de 6 000 gardent le point-in-polygon rapide,
-- puisqu'il tourne à CHAQUE course sur CHAQUE cellule du couloir. L'écart
-- d'aire mesuré reste sous 1 % sur les deux bras principaux.
--
-- ⚠️ ATTRIBUTION OBLIGATOIRE : OpenStreetMap est sous ODbL. La mention
-- « © OpenStreetMap contributors » doit rester visible partout où cette donnée
-- influe sur l'affichage — elle l'est déjà sur la carte, et `app/credits-
-- donnees.tsx` est l'écran qui la porte. Ne pas retirer cette source de là.
--
-- ═══ CE QUE ÇA NE FAIT PAS ═════════════════════════════════════════════════
-- Rien n'est INTERDIT AU COUREUR : on traverse un pont, on longe un quai, la
-- trace est intacte et la course pleinement validée. Seule la CAPTURE des
-- cellules d'eau est refusée. Un joueur qui fait le tour d'un bassin garde donc
-- sa boucle, ses points et son couloir — il ne possède simplement pas l'eau.
--
-- Le périmètre est ROUEN (Saison 0, ADR-006), pas la France : seeder un pays
-- entier chargerait des mégaoctets qu'aucun joueur ne traverse. Les autres
-- villes s'ajouteront à leur ouverture, par la même méthode.
--
-- IDEMPOTENTE : purge des seules lignes `reason like 'water:%'` avant insert —
-- rejouer la migration ne duplique rien, et n'efface aucune zone d'une autre
-- famille (militaire, autoroute…) si elle arrive un jour.
-- ADDITIVE : aucune table, aucune colonne. Rollback = delete des mêmes lignes.

delete from public.no_capture_zones where reason like 'water:%';

insert into public.no_capture_zones (name, geojson, reason) values
